contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Ensure the deciding call is made by `caller` as msg.sender.
        // We cannot change msg.sender directly, so we only test the rule when
        // caller is this contract or the known owner address.
        // To exercise the non-owner path deterministically, we call withdrawAll
        // directly when caller != owner; otherwise we impersonate by calling
        // through the test contract itself (which is the deployer and thus not owner
        // only if the owner was set elsewhere). Since we cannot change msg.sender,
        // we instead test the owner path by having this contract call withdrawAll,
        // and we validate owner status via the public owner() getter.
        address actualOwner = c.owner();

        // Precondition: only run the rule when the caller is either the owner
        // (so withdrawAll should succeed) or not the owner (so it should revert).
        // We use the actualOwner from c to decide which branch applies.
        bool shouldRevert = (caller != actualOwner);

        // Make the deciding call as this test contract. The caller param is used
        // only to express the rule; msg.sender is this contract.
        // To respect the constraint that every state-changing call is top-level,
        // we call withdrawAll directly and capture the revert flag.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: withdrawAll reverts if and only if the effective caller
        // (msg.sender, which is this test contract) is not the owner.
        // Since this contract is not necessarily the owner, we compare against
        // the owner address read via the public getter.
        assert(reverted == (address(this) != actualOwner));
    }

    receive() external payable {}
}
